315 class CD3DX12_DXIL_LIBRARY_SUBOBJECT
316     : public CD3DX12_STATE_OBJECT_DESC::SUBOBJECT_HELPER_BASE
317 {
318 public:
319     CD3DX12_DXIL_LIBRARY_SUBOBJECT() noexcept
320     {
321         Init();
322     }
323     CD3DX12_DXIL_LIBRARY_SUBOBJECT(CD3DX12_STATE_OBJECT_DESC& ContainingStateObject)
324     {
325         Init();
326         AddToStateObject(ContainingStateObject);
327     }
328     CD3DX12_DXIL_LIBRARY_SUBOBJECT(const CD3DX12_DXIL_LIBRARY_SUBOBJECT& other) = delete;
329     CD3DX12_DXIL_LIBRARY_SUBOBJECT& operator=(const CD3DX12_DXIL_LIBRARY_SUBOBJECT& other) = delete;
330     CD3DX12_DXIL_LIBRARY_SUBOBJECT(CD3DX12_DXIL_LIBRARY_SUBOBJECT&& other) = default;
331     CD3DX12_DXIL_LIBRARY_SUBOBJECT& operator=(CD3DX12_DXIL_LIBRARY_SUBOBJECT&& other) = default;
332     void SetDXILLibrary(const D3D12_SHADER_BYTECODE* pCode) noexcept
333     {
334         static const D3D12_SHADER_BYTECODE Default = {};
335         m_Desc.DXILLibrary = pCode ? *pCode : Default;
336     }
337     void DefineExport(
338         LPCWSTR Name,
339         LPCWSTR ExportToRename = nullptr,
340         D3D12_EXPORT_FLAGS Flags = D3D12_EXPORT_FLAG_NONE)
341     {
342         D3D12_EXPORT_DESC Export;
343         Export.Name = m_Strings.LocalCopy(Name);
344         Export.ExportToRename = m_Strings.LocalCopy(ExportToRename);
345         Export.Flags = Flags;
346         m_Exports.push_back(Export);
347         m_Desc.pExports = &m_Exports[0];  // using ugly way to get pointer in case .data() is not defined
348         m_Desc.NumExports = static_cast<UINT>(m_Exports.size());
349     }
350     template<size_t N>
351     void DefineExports(LPCWSTR(&Exports)[N])
352     {
353         for (UINT i = 0; i < N; i++)
354         {
355             DefineExport(Exports[i]);
356         }
357     }
358     void DefineExports(const LPCWSTR* Exports, UINT N)
359     {
360         for (UINT i = 0; i < N; i++)
361         {
362             DefineExport(Exports[i]);
363         }
364     }
365     D3D12_STATE_SUBOBJECT_TYPE Type() const noexcept override
366     {
367         return D3D12_STATE_SUBOBJECT_TYPE_DXIL_LIBRARY;
368     }
369     operator const D3D12_DXIL_LIBRARY_DESC&() const noexcept { return m_Desc; }
370 private:
371     void Init() noexcept
372     {
373         SUBOBJECT_HELPER_BASE::Init();
374         m_Desc = {};
375         m_Strings.clear();
376         m_Exports.clear();
377     }
378     void* Data() noexcept override { return &m_Desc; }
379     D3D12_DXIL_LIBRARY_DESC m_Desc;
380     CD3DX12_STATE_OBJECT_DESC::StringContainer<LPCWSTR, std::wstring> m_Strings;
381     std::vector<D3D12_EXPORT_DESC> m_Exports;
382 };
