519 class CD3DX12_DXIL_SUBOBJECT_TO_EXPORTS_ASSOCIATION
520     : public CD3DX12_STATE_OBJECT_DESC::SUBOBJECT_HELPER_BASE
521 {
522 public:
523     CD3DX12_DXIL_SUBOBJECT_TO_EXPORTS_ASSOCIATION() noexcept
524     {
525         Init();
526     }
527     CD3DX12_DXIL_SUBOBJECT_TO_EXPORTS_ASSOCIATION(CD3DX12_STATE_OBJECT_DESC& ContainingStateObject)
528     {
529         Init();
530         AddToStateObject(ContainingStateObject);
531     }
532     CD3DX12_DXIL_SUBOBJECT_TO_EXPORTS_ASSOCIATION(const CD3DX12_DXIL_SUBOBJECT_TO_EXPORTS_ASSOCIATION& other) = delete;
