1668     {
1669         Init();
1670     }
1671     CD3DX12_GENERIC_PROGRAM_SUBOBJECT(CD3DX12_STATE_OBJECT_DESC& ContainingStateObject)
1672     {
1673         Init();
1674         AddToStateObject(ContainingStateObject);
1675     }
1676     void SetProgramName(LPCWSTR ProgramName)
1677     {
1678         m_Desc.ProgramName = m_Strings.LocalCopy(ProgramName);
1679     }
1680     void AddExport(LPCWSTR exportName)
1681     {
1682         m_Exports.emplace_back(m_Strings.LocalCopy(exportName));
1683         m_numExports++;
1684     }
1685     void AddSubobject(const D3D12_STATE_SUBOBJECT& subobject)
1686     {
1687         m_Subobjects.emplace_back(&subobject);
1688         m_numSubobjects++;
1689     }
1690     D3D12_STATE_SUBOBJECT_TYPE Type() const noexcept override
1691     {
1692         return D3D12_STATE_SUBOBJECT_TYPE_GENERIC_PROGRAM;
1693     }
1694     operator const D3D12_GENERIC_PROGRAM_DESC& () const noexcept { return m_Desc; }
1695     virtual void Finalize() override
1696     {
1697         // Set exports
1698         if (m_numExports > 0)
1699         {
1700             m_ExportsVector.resize(m_numExports);
1701             std::list<LPCWSTR>::iterator exportIt = m_Exports.begin();
1702             for (UINT i = 0; exportIt != m_Exports.end(); i++, exportIt++)
1703             {
1704                 m_ExportsVector[i] = *exportIt;
1705             }
1706             // Below: using ugly way to get pointer in case .data() is not defined
1707             m_Desc.pExports = &m_ExportsVector[0];
1708         }
1709         else
1710         {
1711             m_Desc.pExports = nullptr;
1712         }
1713         m_Desc.NumExports = m_numExports;
1714 
1715         // Set subobjects
1716         if (m_numSubobjects > 0)
1717         {
1718             m_SubobjectsVector.resize(m_numSubobjects);
1719             std::list<D3D12_STATE_SUBOBJECT const*>::iterator subobjectIt = m_Subobjects.begin();
1720             for (UINT i = 0; subobjectIt != m_Subobjects.end(); i++, subobjectIt++)
1721             {
1722                 m_SubobjectsVector[i] = *subobjectIt;
1723             }
1724             // Below: using ugly way to get pointer in case .data() is not defined
1725             m_Desc.ppSubobjects = &m_SubobjectsVector[0];
1726         }
1727         else
1728         {
1729             m_Desc.ppSubobjects = nullptr;
1730         }
1731         m_Desc.NumSubobjects = m_numSubobjects;
1732     }
1733 private:
1734     void Init() noexcept
1735     {
1736         SUBOBJECT_HELPER_BASE::Init();
1737         m_Desc = {};
1738         m_numExports = 0;
1739         m_numSubobjects = 0;
1740     }
1741     void* Data() noexcept override { return &m_Desc; }
1742     D3D12_GENERIC_PROGRAM_DESC m_Desc;
1743     std::list<LPCWSTR> m_Exports;
1744     std::vector<LPCWSTR> m_ExportsVector;
1745     UINT m_numExports;
1746     std::list<D3D12_STATE_SUBOBJECT const*> m_Subobjects;
1747     std::vector<D3D12_STATE_SUBOBJECT const*> m_SubobjectsVector;
1748     UINT m_numSubobjects;
1749     CD3DX12_STATE_OBJECT_DESC::StringContainer<LPCWSTR, std::wstring> m_Strings;
1750 };
