2095     {
2096         Init();
2097     }
2098     CD3DX12_WORK_GRAPH_SUBOBJECT(CD3DX12_STATE_OBJECT_DESC& ContainingStateObject)
2099     {
2100         Init();
2101         AddToStateObject(ContainingStateObject);
2102     }
2103     D3D12_STATE_SUBOBJECT_TYPE Type() const noexcept override
2104     {
2105         return D3D12_STATE_SUBOBJECT_TYPE_WORK_GRAPH;
2106     }
2107     void IncludeAllAvailableNodes()
2108     {
2109         m_Desc.Flags |= D3D12_WORK_GRAPH_FLAG_INCLUDE_ALL_AVAILABLE_NODES;
2110     }
2111     void SetProgramName(LPCWSTR ProgramName)
2112     {
2113         m_Desc.ProgramName = m_Strings.LocalCopy(ProgramName);
2114     }
2115     void AddEntrypoint(D3D12_NODE_ID Entrypoint)
2116     {
2117         m_Entrypoints.emplace_back(D3D12_NODE_ID{ m_Strings.LocalCopy(Entrypoint.Name),Entrypoint.ArrayIndex });
2118         m_NumEntrypoints++;
2119     }
2120 
2121     template<typename T>
2122     T* CreateNode()
2123     {
2124         m_NodeDescs.push_back({});
2125         m_NumNodes++;
2126         T* pNodeHelper = new T(&m_NodeDescs.back());
2127         m_OwnedNodeHelpers.emplace_back(pNodeHelper);
2128         return pNodeHelper;
2129     }
2130     CD3DX12_SHADER_NODE* CreateShaderNode(LPCWSTR Shader = nullptr)
2131     {
2132         auto pNode = CreateNode<CD3DX12_SHADER_NODE>();
2133         pNode->Shader(Shader);
2134         return pNode;
2135     }
2136     CD3DX12_BROADCASTING_LAUNCH_NODE_OVERRIDES* CreateBroadcastingLaunchNodeOverrides(LPCWSTR Shader = nullptr)
2137     {
2138         auto pNode = CreateNode<CD3DX12_BROADCASTING_LAUNCH_NODE_OVERRIDES>();
2139         pNode->Shader(Shader);
2140         return pNode;
2141     }
2142     CD3DX12_COALESCING_LAUNCH_NODE_OVERRIDES* CreateCoalescingLaunchNodeOverrides(LPCWSTR Shader = nullptr)
2143     {
2144         auto pNode = CreateNode<CD3DX12_COALESCING_LAUNCH_NODE_OVERRIDES>();
2145         pNode->Shader(Shader);
2146         return pNode;
2147     }
2148     CD3DX12_THREAD_LAUNCH_NODE_OVERRIDES* CreateThreadLaunchNodeOverrides(LPCWSTR Shader = nullptr)
2149     {
2150         auto pNode = CreateNode<CD3DX12_THREAD_LAUNCH_NODE_OVERRIDES>();
2151         pNode->Shader(Shader);
2152         return pNode;
2153     }
2154     CD3DX12_COMMON_COMPUTE_NODE_OVERRIDES* CreateCommonComputeNodeOverrides(LPCWSTR Shader = nullptr)
2155     {
2156         auto pNode = CreateNode<CD3DX12_COMMON_COMPUTE_NODE_OVERRIDES>();
2157         pNode->Shader(Shader);
2158         return pNode;
2159     }
2160     operator const D3D12_WORK_GRAPH_DESC& () noexcept
2161     {
2162         return m_Desc;
2163     }
2164     virtual void Finalize() override
2165     {
2166         m_EntrypointsVector.resize(m_NumEntrypoints);
2167         std::list<D3D12_NODE_ID>::iterator entryIt = m_Entrypoints.begin();
2168         for (UINT n = 0; n < m_NumEntrypoints; n++, entryIt++)
2169         {
2170             m_EntrypointsVector[n] = *entryIt;
2171         }
2172         m_Desc.NumEntrypoints = m_NumEntrypoints;
2173         m_Desc.pEntrypoints = m_EntrypointsVector.data();
2174 
2175         m_NodeDescsVector.resize(m_NumNodes);
2176         std::list<D3D12_NODE>::iterator nodeIt = m_NodeDescs.begin();
2177         for (UINT n = 0; n < m_NumNodes; n++, nodeIt++)
2178         {
2179             m_NodeDescsVector[n] = *nodeIt;
2180         }
2181         m_Desc.NumExplicitlyDefinedNodes = m_NumNodes;
2182         m_Desc.pExplicitlyDefinedNodes = m_NodeDescsVector.data();
2183     }
2184 private:
2185     void Init() noexcept
2186     {
2187         SUBOBJECT_HELPER_BASE::Init();
2188         m_Desc = {};
2189         m_NodeDescs.clear();
2190         m_NodeDescsVector.clear();
2191         m_NumNodes = 0;
2192         m_NumEntrypoints = 0;
2193     }
2194     void* Data() noexcept override { return &m_Desc; }
2195     D3D12_WORK_GRAPH_DESC m_Desc;
2196     std::list<D3D12_NODE_ID> m_Entrypoints;
2197     UINT m_NumEntrypoints;
2198     std::vector<D3D12_NODE_ID> m_EntrypointsVector;
2199     std::list<D3D12_NODE> m_NodeDescs;
2200     UINT m_NumNodes;
2201     std::vector<D3D12_NODE> m_NodeDescsVector;
2202     CD3DX12_STATE_OBJECT_DESC::StringContainer<LPCWSTR, std::wstring> m_Strings;
2203     std::list<std::unique_ptr<const CD3DX12_NODE_HELPER_BASE>> m_OwnedNodeHelpers;
2204 };
